import { after } from 'next/server'

async function logPageView(path: string) {
  const res = await fetch('https://analytics.example.com/track', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      event: 'page_view',
      path,
      timestamp: Date.now(),
    }),
  })

  if (!res.ok) {
    throw new Error(`Analytics responded with ${res.status}`)
  }
}

export default function Home() {
  after(async () => {
    try {
      await logPageView('/')
    } catch (err) {
      console.error('Failed to log page view:', err)
    }
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Page view is being logged after the response is sent.</p>
    </main>
  )
}

